const showingStep = (
  suggestion: ReadySuggestion,
  history: readonly RefineStep[],
  shown: number,
): ReadySuggestion => {
  const step = history[shown]
  return step === undefined
    ? suggestion
    : {
        ...suggestion,
        history,
        shown,
        replacement: step.replacement,
        rationale: step.rationale,
        diff: adaptiveDiff(suggestion.original, step.replacement),
      }
}

const findReady = (
  state: SuggestionsState,
  id: SuggestionId,
): ReadySuggestion | undefined => {
  const found = findSuggestion(state, id)
  return found?.status === 'ready' ? found : undefined
}

export const beginRefine = (
  state: SuggestionsState,
  id: SuggestionId,
  instruction: Instruction,
): SuggestionsState => {
  const found = findReady(state, id)
  return found === undefined || found.refine.status === 'working'
    ? state
    : replaceItem(state, {
        ...found,
        refine: { status: 'working', instruction },
      })
}

export const resolveRefine = (
  state: SuggestionsState,
  id: SuggestionId,
  result: SuggestionResult,
): SuggestionsState => {
  const found = findReady(state, id)
  if (found?.refine.status !== 'working') return state
  const replacement = matchEdgeWhitespace(found.original, result.replacement)
  if (result.unchanged || replacement === found.replacement) {
    return withNotice(
      replaceItem(state, { ...found, refine: { status: 'idle' } }),
      'no-change',
    )
  }
  const history = [
    ...found.history.slice(0, found.shown + 1),
    {
      instruction: found.refine.instruction,
      replacement,
      rationale: result.rationale,
    },
  ]
  return replaceItem(state, {
    ...showingStep(found, history, history.length - 1),
    refine: { status: 'idle' },
  })
}

export const showVersion = (
  state: SuggestionsState,
  id: SuggestionId,
  index: number,
): SuggestionsState => {
  const found = findReady(state, id)
  return found === undefined ||
    found.refine.status === 'working' ||
    index === found.shown ||
    found.history[index] === undefined
    ? state
    : replaceItem(state, {
        ...showingStep(found, found.history, index),
        refine: { status: 'idle' },
      })
}

export const failRefine = (
  state: SuggestionsState,
  id: SuggestionId,
  error: ClientError,
): SuggestionsState => {
  const found = findReady(state, id)
  return found?.refine.status === 'working'
    ? replaceItem(state, {
        ...found,
        refine: {
          status: 'failed',
          instruction: found.refine.instruction,
          error,
        },
      })
    : state
}

export const retryRefine = (
  state: SuggestionsState,
  id: SuggestionId,
): SuggestionsState => {
  const found = findReady(state, id)
  return found?.refine.status === 'failed'
    ? replaceItem(state, {
        ...found,
        refine: { status: 'working', instruction: found.refine.instruction },
      })
    : state
}

export const cancelRefine = (
  state: SuggestionsState,
  id: SuggestionId,
): SuggestionsState => {
  const found = findReady(state, id)
  return found === undefined || found.refine.status === 'idle'
    ? state
    : replaceItem(state, { ...found, refine: { status: 'idle' } })
}

export const instructionHistory = (
  suggestion: ReadySuggestion,
): readonly string[] =>
  suggestion.history
    .slice(0, suggestion.shown + 1)
    .map((step) => step.instruction.text)

export const failSuggestion = (
  state: SuggestionsState,
  id: SuggestionId,
  error: ClientError,
): SuggestionsState => {
  const found = findSuggestion(state, id)
  return found?.status === 'pending'
    ? replaceItem(state, { ...found, status: 'error', error })
    : state
}

export const retrySuggestion = (
  state: SuggestionsState,
  id: SuggestionId,
): SuggestionsState => {
  const found = findSuggestion(state, id)
  if (found?.status !== 'error') return state
  const { error: _error, ...base } = found
  return replaceItem(state, { ...base, status: 'pending' })
}

  const runRefine = (
    handle: EditorHandle,
    found: ReadySuggestion,
    instruction: Instruction,
    begin: StateEffect<unknown>,
  ): void => {
    const blocks = blocksOf(handle.state)
    const target = targetFromRange(
      blocks,
      textOf(handle.state),
      found,
      found.source,
    )
    const request = {
      target,
      neighbors: getNeighbors(blocks, target),
      history: instructionHistory(found),
      latestReplacement: found.replacement,
      instruction: instruction.text,
      task: refineTaskLabel({ blocks: target.blocks, instruction }),
    }
    handle.dispatch({ effects: begin })
    void execute(
      handle,
      found.id,
      (signal) => client.refineSuggestion({ ...request, signal }),
      settleRefine(found.id),
    )
  }

  const refine = (
    handle: EditorHandle,
    id: SuggestionId,
    instruction: Instruction,
  ): void => {
    const found = findSuggestion(suggestionsOf(handle.state), id)
    if (found?.status !== 'ready' || found.refine.status === 'working') return
    runRefine(
      handle,
      found,
      instruction,
      beginRefineEffect.of({ id, instruction }),
    )
  }

  const retryRefine = (handle: EditorHandle, id: SuggestionId): void => {
    const found = findSuggestion(suggestionsOf(handle.state), id)
    if (found?.status !== 'ready' || found.refine.status !== 'failed') return
    runRefine(handle, found, found.refine.instruction, retryRefineEffect.of(id))
  }

  const actions: SuggestionActions = { ask, retry, refine, retryRefine }

  const extension = [
    suggestionActionsFacet.of(actions),
    'div',
    {
      class: 'cm-ai-version',
      attrs: { role: 'group', 'aria-label': 'Versions' },
    },
    [previous, count, next, instruction],
  )
  return {
    render: (id, version) => {
      target = { id, index: version.index }
      const focused = dom.ownerDocument.activeElement
      previous.disabled = version.locked || version.index === 0
      next.disabled = version.locked || version.index === version.count - 1
      count.textContent = `${version.index + 1} / ${version.count}`
      instruction.textContent = version.instruction
      instruction.title = version.instruction
      const stuck = [previous, next].find(
        (button) => button === focused && button.disabled,
      )
      const other = stuck === previous ? next : previous
      if (stuck !== undefined && !other.disabled) other.focus()
      return dom
    },
  }
}

const refineButton = (
  view: EditorView,
  { suggestion, refineOpen }: CardContent,
) =>
  suggestion.refine.status === 'working'
    ? actionButton(view, 'Refining…', undefined, () => undefined, {
        disabled: true,
        busy: true,
      })
    : actionButton(
        view,
        'Refine',
        shortcutLabel('K'),
        () =>
          view.dispatch({
            effects: refineOpen
              ? closeRefineEffect.of(null)
              : openRefineEffect.of(suggestion.id),
          }),
        { refocus: refineOpen, expanded: refineOpen },
      )

const refineError = (
  view: EditorView,
  { refine, id }: ReadySuggestion,
  withRetry: boolean,
) =>
  refine.status === 'failed'
    ? [
        el('div', { class: 'cm-ai-card-error', attrs: { role: 'alert' } }, [
          el('span', { class: 'cm-ai-error-message' }, [
            describeError(refine.error),
          ]),
          ...(withRetry
            ? [
                actionButton(view, 'Retry', undefined, () =>
                  view.state
                    .facet(suggestionActionsFacet)
                    ?.retryRefine(view, id),
                ),
              ]
            : []),
        ]),
      ]
    : []

const renderCard = (
  view: EditorView,
  content: CardContent,
  { form }: RefineForm,
  versionNav: VersionNav,
): Node[] => {
  const { suggestion, showRationale, showActions, refineOpen, version } =
    content
  return [
    ...(version === null ? [] : [versionNav.render(suggestion.id, version)]),
    ...(showRationale
      ? [el('p', { class: 'cm-ai-rationale' }, [suggestion.rationale])]
      : []),
    ...(showActions
      ? [
          el('div', { class: 'cm-ai-card-actions' }, [
            actionButton(view, 'Accept', shortcutLabel('↵'), () =>
              acceptSuggestionById(view, suggestion.id),
            ),
            actionButton(view, 'Reject', 'Esc', () =>
              rejectSuggestionById(view, suggestion.id),
            ),
            refineButton(view, content),
          ]),
          ...(refineOpen ? [form] : []),
        ]
      : []),
    ...refineError(view, suggestion, showActions),
  ]
}

const openedRefine = (update: ViewUpdate): boolean =>
  update.transactions.some((transaction) =>
    transaction.effects.some((effect) => effect.is(openRefineEffect)),
  )

const cardCreator =
  (kind: CardKind, placement: CardPlacement) =>
  (view: EditorView): TooltipView => {
    const refineForm = createRefineForm(view)
    const versionNav = createVersionNav(view)
    const dom = el('div', {
      class: `cm-ai-card cm-ai-card-${kind} cm-ai-card-${placement}`,
      attrs: {
